  max(
    ("asset"."localDateTime" AT TIME ZONE 'UTC'::text)::date
  ) as "endDate",
  max("asset"."updatedAt") as "lastModifiedAssetTimestamp",
  count("asset"."id")::int as "assetCount"
from
  "asset"
  inner join "album_asset" on "album_asset"."assetId" = "asset"."id"
where
  "asset"."visibility" in ('archive', 'timeline')
  and (
    not (
      exists (
        select
          1
        from
          tag_asset
          join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
          join tag on tag.id = tag_closure.id_ancestor
        where
          tag_asset."assetId" = "asset"."id"
          and tag."isPrivate" = true
      )
      or exists (
        select
          1
        from
          asset as private_asset
        where
          private_asset.id = "asset"."id"
          and private_asset.visibility = 'locked'
      )
      or exists (
        select
          1
        from
          asset as still
        where
          still."livePhotoVideoId" = "asset"."id"
          and (
            still.visibility = 'locked'
            or exists (
              select
                1
              from
                tag_asset
                join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
                join tag on tag.id = tag_closure.id_ancestor
              where
                tag_asset."assetId" = "still"."id"
                and tag."isPrivate" = true
            )
          )
      )
    )
  )
  and "album_asset"."albumId" in ($1)
  and "asset"."deletedAt" is null
group by
  "album_asset"."albumId"

