                  join tag on tag.id = tag_closure.id_ancestor
                where
                  tag_asset."assetId" = "still"."id"
                  and tag."isPrivate" = true
              )
            )
        )
      )
  ) as "hasPrivateAssets",
  (
    select
      coalesce(json_agg(agg), '[]')
    from
      (
        select
          "album_user"."role",
          (
            select
              to_json(obj)
            from
              (
                select
                  "id",
                  "name",
                  "email",
                  "avatarColor",
                  "profileImagePath",
                  "profileChangedAt"
                from
                  (
                    select
                      1
                  ) as "dummy"
              ) as obj
          ) as "user"
        from
          "album_user"
          inner join "user" on "user"."id" = "album_user"."userId"
        where
          "album_user"."albumId" = "album"."id"
        order by
          "album_user"."role",
          "album_user"."userId" = $6 desc,
          "user"."name" asc
      ) as agg
  ) as "albumUsers",
  (
    select
      coalesce(json_agg(agg), '[]')
    from
      (
        select
          "shared_link".*
        from
          "shared_link"
        where
          "shared_link"."albumId" = "album"."id"
      ) as agg
  ) as "sharedLinks"
from
  "album"
  inner join "album_user" on "album_user"."albumId" = "album"."id"
  and "album_user"."userId" = $7
where
  "album"."deletedAt" is null
  and "album_user"."role" = 'owner'
  and (
    exists (
      select
      from
        "album_user" as "au"
      where
        "au"."albumId" = "album"."id"
        and "au"."role" != 'owner'
    )
    or exists (
      select
      from
        "shared_link"
      where
        "shared_link"."albumId" = "album"."id"
    )
  )
order by
  "album"."createdAt" desc

-- AlbumRepository.getAllIds
select
  "album"."id"
from
  "album"
  inner join "album_user" on "album_user"."albumId" = "album"."id"
  and "album_user"."userId" = $1
where
  "album"."deletedAt" is null
  and "album_user"."role" = 'owner'
  and (
    exists (
      select
      from
        "album_user" as "au"
      where
        "au"."albumId" = "album"."id"
        and "au"."role" != 'owner'
    )
    or exists (
      select
      from
        "shared_link"
      where
        "shared_link"."albumId" = "album"."id"
    )
  )
order by
  "album"."createdAt" desc

-- AlbumRepository.removeAssetsFromAll
delete from "album_asset"
where
  "album_asset"."assetId" in ($1)

-- AlbumRepository.getAssetIds
select
  *
from
  "album_asset"
where
  "album_asset"."albumId" = $1
  and "album_asset"."assetId" in ($2)

-- AlbumRepository.addAssetIds
insert into
  "album_asset"
select
  $1::uuid as "albumId",
  unnest($2::uuid[]) as "assetId"
from
  (
    select
      1
  ) as "dummy"
on conflict do nothing

-- AlbumRepository.create
with
  "album" as (
    insert into
      "album" ("albumName")
    values
      ($1)
    returning
      *
  ),
  "album_user" as (
    insert into
      "album_user"
    select
      "album"."id" as "albumId",
      unnest($2::uuid[]) as "userId",
      unnest($3::album_user_role_enum[]) as "role"
    from
      "album"
    returning
      "album_user"."albumId",
      "album_user"."userId",
      "album_user"."role"
  ),
  "album_asset" as (
    insert into
      "album_asset"
    select
      "album"."id" as "albumId",
      unnest($4::uuid[]) as "assetId"
    from
      "album"
    on conflict do nothing
    returning
      "album_asset"."albumId",
      "album_asset"."assetId"
  )
select
  "album".*,
  (
    select
      coalesce(json_agg(agg), '[]')
    from
      (
        select
          "album_user"."role",
          (
            select
              to_json(obj)
            from
              (
                select
                  "id",
                  "name",
                  "email",
                  "avatarColor",
                  "profileImagePath",
                  "profileChangedAt"
                from
                  (
                    select
                      1
                  ) as "dummy"
              ) as obj
          ) as "user"
        from
          "album_user"
          inner join "user" on "user"."id" = "album_user"."userId"
        where
          "album_user"."albumId" = "album"."id"
        order by
          "album_user"."role",
          "user"."name" asc
      ) as agg
  ) as "albumUsers"
from
  "album"

-- AlbumRepository.getContributorCounts
select
  "asset"."ownerId" as "userId",
  count(*) as "assetCount"
from
  "album_asset"
  inner join "asset" on "asset"."id" = "assetId"
where
  "asset"."deletedAt" is null
  and (
    not (
      exists (
        select
          1
        from
          tag_asset
          join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
          join tag on tag.id = tag_closure.id_ancestor
        where
          tag_asset."assetId" = "asset"."id"
          and tag."isPrivate" = true
      )
      or exists (
        select
          1
        from
          asset as private_asset
        where
          private_asset.id = "asset"."id"
          and private_asset.visibility = 'locked'
      )
      or exists (
        select
          1
        from
          asset as still
        where
          still."livePhotoVideoId" = "asset"."id"
          and (
            still.visibility = 'locked'
            or exists (
              select
                1
              from
                tag_asset
                join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
                join tag on tag.id = tag_closure.id_ancestor
              where
                tag_asset."assetId" = "still"."id"
                and tag."isPrivate" = true
            )
          )
      )
    )
  )
  and "album_asset"."albumId" = $1
group by
  "asset"."ownerId"
order by
  "assetCount" desc

-- AlbumRepository.copyAlbums
insert into
  "album_asset"
select
  "album_asset"."albumId",
  $1 as "assetId"
from
  "album_asset"
where
  "album_asset"."assetId" = $2
on conflict do nothing
